int main(void) {
    my_set_policy(BUDDY);
    size_t num_ops = sizeof(ops) / sizeof(ops[0]);
    for (size_t i = 0; i < num_ops; i++) {
        int op = ops[i].op;
        int a = ops[i].a;
        int b = ops[i].b;
        int c = ops[i].c;
        switch (op) {
            case 1: {
                ptrs[a] = my_malloc((size_t)b);
                if (!ptrs[a]) {
                    printf("UNEXPECTED NULL buddy malloc at %zu\n", i);
                } else {
                    size_t lim = (size_t)b < 32 ? (size_t)b : 32;
                    for (size_t k = 0; k < lim; k++) {
                        ptrs[a][k] = (unsigned char)((c + k * 7) & 0xFF);
                    }
                }
                break;
            }
            case 2: {
                void *p = my_malloc((size_t)a);
                if (p != NULL) printf("EXPECTED NULL buddy malloc at %zu\n", i);
                break;
            }
            case 3: {
                for (int k = 0; k < b; k++) {
                    unsigned char exp = (unsigned char)((c + k * 7) & 0xFF);
                    if (ptrs[a][k] != exp) {
                        printf("BUDDY DATA CORRUPT at %zu\n", i);
                        break;
                    }
                }
                my_free(ptrs[a]);
                ptrs[a] = NULL;
                break;
            }
            case 4:
                my_heap_dump();
                break;
        }
    }
    return 0;
}
